56	static ut16 omf_get_idx(const ut8 *buf, int buf_size) {
57		if (buf_size < 2) {
58			return 0;
59		}
60		if (*buf & 0x80) {
61			return (ut16)((*buf & 0x7f) * 0x100 + buf[1]);
62		}
63		return *buf;
64	}
