66	static void free_lname(OMF_multi_datas *lname) {
67		ut32 ct = 0;
68	
69		while (ct < lname->nb_elem) {
70			R_FREE (((char **)lname->elems)[ct]);
71			ct++;
72		}
73		R_FREE (lname->elems);
74		R_FREE (lname);
75	}
