182	static ut32 omf_count_symb(ut16 total_size, ut32 ct, const ut8 *buf, int bits) {
183		ut32 nb_symb = 0;
184		while (ct < total_size - 1) {
185			ct += buf[ct] + 1 + (bits == 32 ? 4 : 2);
186			if (ct > total_size - 1) {
187				return nb_symb;
188			}
189			if (buf[ct] & 0x80) {
190				ct += 2;
191			} else {
192				ct++;
193			}
194			nb_symb++;
195		}
196		return nb_symb;
197	}
