437	static ut32 count_omf_record_type(r_bin_omf_obj *obj, ut8 type) {
438		OMF_record_handler *tmp = obj->records;
439		ut32 ct = 0;
440	
441		while (tmp) {
442			if (((OMF_record *)tmp)->type == type) {
443				ct++;
444			}
445			tmp = tmp->next;
446		}
447		return ct;
