463	static OMF_record_handler *get_next_omf_record_type(OMF_record_handler *tmp, ut8 type) {
464		while (tmp) {
465			if (((OMF_record *)tmp)->type == type) {
466				return (tmp);
467			}
468			tmp = tmp->next;
469		}
470		return NULL;
